<div class="row"><div class="col-md-12"><h3><i class="fa fa-random"></i> TRAMOS / PARADAS DE RUTA</h3><div class="alert alert-info">Ordene las paradas intermedias. Origen=0 y destino=10000. Use 100, 200, 300...</div></div><div class="col-md-5"><div class="box box-primary"><div class="box-body"><label>Ruta</label><select id="tramo_ruta_id" class="form-control" onchange="tramo_cargar()"><option value="0">-- SELECCIONE --</option><?php foreach($rutas as $r){ ?><option value="<?php echo (int)$r['ruta_id']; ?>"><?php echo html_escape($r['ruta_nombre'].' · '.$r['origen_nombre'].' → '.$r['destino_nombre']); ?></option><?php } ?></select><br><label>Parada</label><select id="tramo_parada_id" class="form-control"><option value="0">-- SELECCIONE --</option><?php foreach($paradas as $p){ ?><option value="<?php echo (int)$p['parada_id']; ?>"><?php echo html_escape($p['parada_nombre']); ?></option><?php } ?></select><br><label>Orden</label><input type="number" id="tramo_orden" class="form-control" value="100"><br><button class="btn btn-success btn-block" onclick="tramo_guardar()">AGREGAR / ACTUALIZAR</button></div></div></div><div class="col-md-7"><div class="box box-primary"><div class="box-body"><table class="table table-bordered"><thead><tr><th>ORDEN</th><th>PUNTO</th><th>TIPO</th><th></th></tr></thead><tbody id="tramo_lista"></tbody></table></div></div></div></div><script>
function tramo_cargar(){var id=$('#tramo_ruta_id').val();$.post('<?php echo site_url("tramo/lista"); ?>',{ruta_id:id},function(r){if(typeof r==='string')r=JSON.parse(r);var h='';$.each(r.paradas||[],function(_,x){h+='<tr><td>'+x.rutaparada_orden+'</td><td><b>'+x.rutaparada_nombre+'</b></td><td>'+x.rutaparada_tipo+'</td><td>'+(x.rutaparada_tipo==='PARADA'?'<button class="btn btn-xs btn-danger" onclick="tramo_eliminar('+x.rutaparada_id+')">X</button>':'')+'</td></tr>';});$('#tramo_lista').html(h);},'json');}
function tramo_guardar(){$.post('<?php echo site_url("tramo/guardar"); ?>',{ruta_id:$('#tramo_ruta_id').val(),parada_id:$('#tramo_parada_id').val(),orden:$('#tramo_orden').val()},function(r){if(typeof r==='string')r=JSON.parse(r);alert(r.mensaje||'OK');if(r.ok)tramo_cargar();},'json');}
function tramo_eliminar(id){if(!confirm('¿Retirar parada?'))return;$.post('<?php echo site_url("tramo/eliminar"); ?>',{rutaparada_id:id},function(){tramo_cargar();},'json');}
</script>